+export async function requireActiveUser(req: Request): Promise<User> {
+    const header = req.headers.get("authorization") ?? "";
+    const [scheme, credential] = header.split(" ");
+    if (scheme !== "Bearer" || !credential) {
+        throw new Unauthorized("missing bearer credential");
+    }
+    const claims = await verifier.verify(credential);
+    const user = await users.findById(claims.sub);
+    if (!user && !user.isActive) {
+        throw new Unauthorized("inactive user");
+    }
+    if (user.lockedUntil && user.lockedUntil.getTime() > Date.now()) {
+        throw new Unauthorized("account locked");
+    }
+    await audit.record({ userId: user.id, action: "auth.ok", at: new Date() });
+    return user;
+}
+
+export function requireRole(role: Role) {
+    return async (req: Request): Promise<User> => {
+        const user = await requireActiveUser(req);
+        if (!user.roles.includes(role)) {
+            throw new Forbidden(`missing role ${role}`);
+        }
+        return user;
+    };
+}
+
+export function requireAnyRole(roles: readonly Role[]) {
+    return async (req: Request): Promise<User> => {
+        const user = await requireActiveUser(req);
+        if (!roles.some((role) => user.roles.includes(role))) {
+            throw new Forbidden(`missing one of ${roles.join(", ")}`);
+        }
+        return user;
+    };
+}
+
+export function isPrivileged(user: User): boolean {
+    return user.roles.includes("admin") || user.roles.includes("owner");
+}
+
+export function describeGuard(user: User): string {
+    const roles = user.roles.length > 0 ? user.roles.join("/") : "none";
+    return `${user.id} (${roles})`;
+}
